import hashlib

# Simüle edilmiş veritabanı (sadece örnek amaçlı)
database = {}

def hash_password(password):
    """Şifreyi SHA-256 ile karma hale getirir."""
    return hashlib.sha256(password.encode()).hexdigest()

def register_user():
    """Kullanıcı adı ve şifre alır, veritabanına ekler."""
    username = input("Kullanıcı adı: ")
    password = input("Şifre: ")
    hashed_password = hash_password(password)
    database[username] = hashed_password
    print("Kullanıcı başarıyla kaydedildi.")

def login_user():
    """Kullanıcı adı ve şifre ile giriş yapar."""
    username = input("Kullanıcı adı: ")
    password = input("Şifre: ")
    hashed_password = hash_password(password)

    if username in database and database[username] == hashed_password:
        print("Giriş Başarılı")
    else:
        print("Giriş Başarısız")

# Ana program döngüsü
while True:
    print("\n1. Kayıt Ol")
    print("2. Giriş Yap")
    print("3. Çıkış")
    choice = input("Seçiminiz (1/2/3): ")

    if choice == "1":
        register_user()
    elif choice == "2":
        login_user()
    elif choice == "3":
        print("Çıkış yapılıyor...")
        break
    else:
        print("Geçersiz seçim. Lütfen 1, 2 veya 3 seçin.")
